package com.yonlab.vision;
import java.util.*;
/** Official YOLOX raw-head grid decoding and class-agnostic NMS in original pixels. */
final class OneYoloXMath {
 static final class Box {final int cls;final float score,left,top,right,bottom;Box(int c,float s,float l,float t,float r,float b){cls=c;score=s;left=l;top=t;right=r;bottom=b;}}
 static List<Box> decode(float[][] rows,int width,int height,float threshold){if(rows.length!=3549||width<1||height<1||!Float.isFinite(threshold)||threshold<0||threshold>1)throw new IllegalArgumentException("YOLOX tensor");List<Box> out=new ArrayList<>();double ratio=Math.min(416d/width,416d/height);int index=0;for(int stride:new int[]{8,16,32}){int side=416/stride;for(int y=0;y<side;y++)for(int x=0;x<side;x++){float[] row=rows[index++];if(row.length!=85)throw new IllegalArgumentException("YOLOX output width");boolean valid=true;for(float v:row)valid&=Float.isFinite(v);if(!valid||row[4]<0||row[4]>1)continue;int cls=0;for(int c=1;c<80;c++)if(row[5+c]>row[5+cls])cls=c;float score=row[4]*row[5+cls];if(score<=threshold||score>1||row[2]>20||row[3]>20)continue;double cx=(row[0]+x)*stride/ratio,cy=(row[1]+y)*stride/ratio,w=Math.exp(row[2])*stride/ratio,h=Math.exp(row[3])*stride/ratio;if(!Double.isFinite(w)||!Double.isFinite(h)||w<=0||h<=0)continue;float l=(float)(cx-w*.5),t=(float)(cy-h*.5),r=(float)(cx+w*.5),b=(float)(cy+h*.5);if(r>l&&b>t)out.add(new Box(cls,score,l,t,r,b));}}out.sort((a,b)->Float.compare(b.score,a.score));List<Box> kept=new ArrayList<>();for(Box box:out){boolean duplicate=false;for(Box prior:kept)if(iou(box,prior)>.45){duplicate=true;break;}if(!duplicate){kept.add(box);if(kept.size()>=100)break;}}return kept;}
 static double iou(Box a,Box b){double w=Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left)+1),h=Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top)+1);double intersection=w*h,union=(a.right-a.left+1)*(a.bottom-a.top+1)+(b.right-b.left+1)*(b.bottom-b.top+1)-intersection;return union>0?intersection/union:0;}
}
